// 1: Feed availability: status, response time, content type
const maxMs = Number(pm.environment.get("maxResponseTimeMs"));

pm.test("1.a: Status code is 200", () => {
    pm.response.to.have.status(200);
});

pm.test(`1.b: Response time is under ${maxMs} ms`, () => {
    pm.expect(pm.response.responseTime).to.be.below(maxMs);
});

pm.test("1.c: Content type is XML", () => {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("xml");
});

// 2: Feed structure: valid XML with the correct root element and a valid publishing date
let feed = null;
try {
    feed = xml2Json(pm.response.text());
} catch (e) {}

const publishedDate = feed?.DataSet?.Header?.PublishingDate;

pm.test("2.a: Response is valid XML with a DataSet root element", () => {
    pm.expect(feed).to.have.property("DataSet");
});

pm.test("2.b: Publishing date is a real date in YYYY-MM-DD format", () => {
    pm.expect(new Date(publishedDate).toISOString().slice(0, 10)).to.equal(publishedDate);
});

// 3: Currency rates: EUR, USD and GBP are present and every rate is a number greater than 0
const rates = [].concat(feed?.DataSet?.Body?.Cube?.Rate || []).map(r => ({
    currency: r.$?.currency,
    value: Number(r._)
}));

pm.test("3.a: EUR, USD and GBP rates are present", () => {
    pm.expect(rates.map(r => r.currency)).to.include.members(["EUR", "USD", "GBP"]);
});

pm.test("3.b: Every rate is a number greater than 0", () => {
    pm.expect(rates.filter(r => !(r.value > 0))).to.be.empty;
});

// 4: Feed recency: publishing date is not in the future and not older than the allowed number of days
const maxDays = Number(pm.environment.get("recencyDays"));
const publishedDaysAgo = Math.floor((Date.now() - new Date(publishedDate)) / 86400000);

pm.test(`4.a: Publishing date is not in the future and at most ${maxDays} days old`, () => {
    pm.expect(publishedDaysAgo).to.be.within(0, maxDays);
});

// 5: Invalid path: a non existent file cannot return data
pm.test("5.a: Response does not contain exchange-rate data", () => {
    pm.expect(pm.response.text()).to.not.include("<DataSet");
});

// 6: SG share price: status, response time, success flag, price, change, date
const maxMs = Number(pm.environment.get("maxResponseTimeMs"));
const maxDays = Number(pm.environment.get("recencyDays"));

let q = {};
try {
    q = pm.response.json();
} catch (e) {}

pm.test("6.a: Status code is 200", () => {
    pm.response.to.have.status(200);
});

pm.test(`6.b: Response time is under ${maxMs} ms`, () => {
    pm.expect(pm.response.responseTime).to.be.below(maxMs);
});

pm.test("6.c: Success flag is true", () => {
    pm.expect(q.success).to.equal("true");
});

pm.test("6.d: Price is a number greater than 0", () => {
    pm.expect(Number(q.price)).to.be.above(0);
});

pm.test("6.e: Price change is a number", () => {
    pm.expect(parseFloat(q.diff)).to.not.be.NaN;
});

pm.test(`6.f: Date is not in the future and at most ${maxDays} days old`, () => {
    const isoDate = (q.date || "").split("/").reverse().join("-");
    const daysOld = Math.floor((Date.now() - new Date(isoDate)) / 86400000);
    pm.expect(daysOld).to.be.within(0, maxDays);
});
